int compat_ioctl_get_timestamp(struct net *net, struct socket *sock,
                               unsigned int cmd, void __user *up)
{
    int ret;
    mm_segment_t old_fs;
    struct timespec ts;

    old_fs = get_fs();
    set_fs(KERNEL_DS);

    ret = sock->ops->ioctl(sock, cmd, (unsigned long)&ts);

    set_fs(old_fs);

