int compat_sock_ioctl_getts(struct net *net, struct socket *sock, unsigned int cmd, void __user *up)
{
    int error;
    mm_segment_t old_fs = get_fs();

    set_fs(KERNEL_DS);
    error = sock->ops->ioctl(sock, cmd, (unsigned long)up);
    set_fs(old_fs);

    if (error >= 0) {
        if (copy_to_user(up, up, error)) {
            return -EFAULT;
        }
    }

    return error;
}

int compat_sock_ioctl_get_timestamp(struct net *net, struct socket *sock,
                                    unsigned int cmd, void __user *up)
{
    int ret;
    unsigned long orig_addr_space;
    struct timeval tv;

    orig_addr_space = current->thread.addr_space;
    set_fs(KERNEL_DS);

    ret = sock->ops->ioctl(sock, cmd, (unsigned long)&tv);
    if (ret < 0)
        goto restore;

    if (copy_to_user(up, &tv, sizeof(tv)))
        ret = -EFAULT;

restore:
    set_fs(orig_addr_space);
    return ret;
}

int compat_sock_ioctl_timestamp(struct net *net, struct socket *sock, unsigned int cmd, void __user *up)
{
    int ret = -EFAULT;
    struct timespec ts;
    mm_segment_t old_fs;

    if (cmd != SIOCGSTAMP)
        return -EINVAL;

    old_fs = get_fs();
    set_fs(KERNEL_DS);

    ret = sock->ops->ioctl(sock, cmd, (unsigned long)&ts);

    set_fs(old_fs);

    if (!ret)
        ret = copy_to_user(up, &ts, sizeof(ts)) ? -EFAULT : 0;

    return ret;
}
